// src/identity/erase.ts
// ---------------------------------------------------------------------------
// CW28: the right to be forgotten, end to end.
//
// A person is a shopper id and every browser ever linked to it. Erasing them
// means, in this order: the link table (so no browser resolves to them again),
// every profile that held their behaviour (the person's session and each
// browser's, or the shopper objects on the object host), and their rows in the
// ledger, which the other session's eraseVisitorLedger() handles with a
// tombstone every reader honours at once and a nightly rewrite of the batches.
//
// A visitor id that was never linked is erased on its own: its profile and its
// ledger rows. A visitor id that was linked erases the whole person, because
// the browser's behaviour already folded into them and a partial erasure would
// leave it there.
//
// What this does not reach: ODP (Optimizely Data Platform) holds its own copy
// under the vuid derived from the id; its erasure is ODP's API, run by the
// brand's operator, and the receipt says so. Ledger Analytics Engine points omit
// visitor/session IDs, but earlier route writers stored raw subject events.
// This operation does not erase historical Analytics Engine rows or Worker /
// application logs; future-write containment does not remove that history.
// ---------------------------------------------------------------------------

import type { Env } from '@/types/env';
import type { TenantId } from '@/tenancy/tenant';
import { shopperObject } from '@/tenancy/objects';
import { SessionManager } from '@/services/SessionManager';
import { IdentityStore } from '@/identity/store';
import { isShopperId } from '@/identity/shopperId';
import { eraseVisitorLedger } from '@/ledger/erasure';

export interface EraseReceipt {
  tenant: string;
  /** What was asked for. */
  subject: { visitorId?: string; shopperId?: string };
  /** The person this resolved to, if the subject was linked. */
  shopperId: string | null;
  /** Every id whose profile and ledger rows were erased. */
  erased: string[];
  profiles: Array<{ id: string; host: 'session' | 'object'; result: 'erased' | 'absent' | 'failed' }>;
  ledger: Array<{ id: string; tombstone: string | null; ring: string }>;
  links: { visitors: number; shopper: boolean };
  /** What this cannot reach, said plainly. */
  notReached: string[];
  actor: string;
  at: number;
}

async function eraseProfile(env: Env, tenant: TenantId, id: string, ownSessionId: string | null): Promise<EraseReceipt['profiles'][number]> {
  if ((env.REFLEX_HOST ?? 'session') === 'do') {
    try {
      const res = await shopperObject(env.SHOPPER_REFLEX, id, tenant).fetch('https://shopper-reflex/reset', { method: 'POST' });
      return { id, host: 'object', result: res.ok ? 'erased' : 'failed' };
    } catch { return { id, host: 'object', result: 'failed' }; }
  }
  const sm = new SessionManager(env, { tenant });
  try {
    const sid = await sm.resolveSessionIdByUserId(id);
    // The record the pointer names (the person's, after a link), then the pointer
    // itself and the browser's own pre-link record, which nothing else reaches.
    const ok = sid ? await sm.deleteSession(sid) : false;
    await sm.forgetVisitor(id, ownSessionId);
    return { id, host: 'session', result: sid || ownSessionId ? (ok || !sid ? 'erased' : 'failed') : 'absent' };
  } catch { return { id, host: 'session', result: 'failed' }; }
}

export async function eraseSubject(
  env: Env,
  tenant: TenantId,
  subject: { visitorId?: string; shopperId?: string },
  actor: string,
  now = Date.now(),
): Promise<EraseReceipt> {
  const store = new IdentityStore(env.SESSIONS as never, tenant);

  // 1. Who is being forgotten.
  let shopperId: string | null = subject.shopperId ?? null;
  if (!shopperId && subject.visitorId) shopperId = isShopperId(subject.visitorId) ? subject.visitorId : await store.resolveVisitor(subject.visitorId);

  const ids = new Map<string, string | null>();   // id → the browser's own session record, when the link remembered one
  let links: EraseReceipt['links'] = { visitors: 0, shopper: false };
  if (shopperId) {
    const own = new Map<string, string>();
    const rec = await store.shopper(shopperId);
    for (const v of rec?.visitors ?? []) { const l = await store.visitorLink(v.visitorId); if (l?.ownSessionId) own.set(v.visitorId, l.ownSessionId); }
    const { visitors } = await store.erase(shopperId);
    links = { visitors: visitors.length, shopper: true };
    ids.set(shopperId, null);
    for (const v of visitors) ids.set(v, own.get(v) ?? null);
    if (subject.visitorId && !ids.has(subject.visitorId)) ids.set(subject.visitorId, null);
  } else if (subject.visitorId) {
    const { ownSessionId } = await store.eraseVisitor(subject.visitorId);
    ids.set(subject.visitorId, ownSessionId);
  }

  // 2. Every profile, then 3. every ledger row.
  const profiles: EraseReceipt['profiles'] = [];
  const ledger: EraseReceipt['ledger'] = [];
  for (const [id, ownSessionId] of ids) {
    profiles.push(await eraseProfile(env, tenant, id, ownSessionId));
    try {
      const r = await eraseVisitorLedger(env, tenant, id, actor, now);
      ledger.push({ id, tombstone: r.tombstone.key, ring: r.ring });
    } catch {
      ledger.push({ id, tombstone: null, ring: 'failed' });
    }
  }

  return {
    tenant, subject, shopperId, erased: [...ids.keys()], profiles, ledger, links,
    notReached: [
      'ODP: the profile under the derived vuid is erased through ODP\'s own API by the brand\'s operator',
      'Analytics Engine: historical subject-bearing route events are not erased by this operation; dataset contents, retention and disposition remain unverified',
      'Worker/application logs: historical request, event and subject data are not erased by this operation; other logging paths remain and retention/disposition are unverified',
    ],
    actor, at: now,
  };
}

// src/identity/store.ts
// ---------------------------------------------------------------------------
// The link table: which browsers belong to which person.
//
// Two records, both under the brand's prefix in the SESSIONS namespace, beside
// the profiles they describe:
//
//   identity:visitor:{visitorId}   → the shopper this browser was linked to,
//                                    when, how sure we were, and where it came
//                                    from. A browser re-linked to a different
//                                    account keeps its history here.
//   identity:shopper:{shopperId}   → every browser linked to this person, and
//                                    whether the id was minted with a salt.
//
// The raw account id appears in neither. What the warehouse can join on is the
// shopper id, which is on every record that leaves; the site's backend can
// compute it (same salt, same hash) or ask `POST /v1/:tenant/identity/resolve`.
//
// These are NOT on the decision path. A request for a linked browser is served
// from the profile that already carries the pointer (SessionManager's
// `forwardTo`, the shopper object's `forwardTo`), so an anonymous visitor costs
// nothing here and a linked one costs nothing here either. The table is for the
// link itself, for resolution queries, and for doc 22's `identity` scope.
// ---------------------------------------------------------------------------

import { DEFAULT_TENANT, TenantKV, type KVLike, type TenantId } from '@/tenancy/tenant';
import type { Assurance } from '@/identity/assertion';
import { isShopperId } from '@/identity/shopperId';

/** A link lives a long time; it is the memory the scope promises identity lengthens. */
export const LINK_TTL_S = 400 * 24 * 3600;

export type LinkSource = 'login' | 'signup' | 'checkout' | 'import' | 'other';

export interface VisitorLink {
  visitorId: string;
  shopperId: string;
  linkedAt: number;
  assurance: Assurance;
  source: LinkSource;
  /** Earlier links this browser had, newest first. A shared computer leaves a trail here. */
  previous?: Array<{ shopperId: string; linkedAt: number; until: number }>;
  /**
   * CW28. The browser's own session record on the session host, which forwards
   * to the person after the link and is reachable by nothing else. Remembered so
   * an erasure can delete what the browser learned before it was anyone's.
   */
  ownSessionId?: string;
}

export interface ShopperRecord {
  shopperId: string;
  createdAt: number;
  salted: boolean;
  visitors: Array<{ visitorId: string; linkedAt: number; assurance: Assurance; source: LinkSource }>;
  /** Historical rows applied to this shopper, if any: how many and the latest event time. */
  history?: { rows: number; latestAt: number; appliedAt: number };
}

export class IdentityStore {
  private readonly kv: KVLike;

  constructor(kv: KVLike, readonly tenant: TenantId = DEFAULT_TENANT) {
    this.kv = new TenantKV(kv, tenant);
  }

  private vkey(visitorId: string) { return `identity:visitor:${visitorId}`; }
  private skey(shopperId: string) { return `identity:shopper:${shopperId}`; }

  async visitorLink(visitorId: string): Promise<VisitorLink | null> {
    return ((await this.kv.get(this.vkey(visitorId), 'json')) as VisitorLink | null) ?? null;
  }

  async shopper(shopperId: string): Promise<ShopperRecord | null> {
    return ((await this.kv.get(this.skey(shopperId), 'json')) as ShopperRecord | null) ?? null;
  }

  /**
   * The person behind an id, or null when the id is an unlinked browser.
   * A shopper id resolves to itself: once a client carries it, it is the person.
   * This is the resolver doc 22's `identity` attribution scope needs.
   */
  async resolveVisitor(id: string): Promise<string | null> {
    if (isShopperId(id)) return id;
    return (await this.visitorLink(id))?.shopperId ?? null;
  }

  /**
   * Record that a browser belongs to a person. Idempotent for the same pair;
   * a different person moves the browser and keeps the old link in `previous`.
   * Returns what changed, so the caller knows whether a merge is due: a browser
   * already on this shopper has nothing left to merge.
   */
  async link(input: {
    visitorId: string; shopperId: string; assurance: Assurance; source: LinkSource; salted: boolean; now?: number;
  }): Promise<{ link: VisitorLink; shopper: ShopperRecord; outcome: 'linked' | 'already' | 'relinked' }> {
    const now = input.now ?? Date.now();
    const existing = await this.visitorLink(input.visitorId);

    let outcome: 'linked' | 'already' | 'relinked' = 'linked';
    let previous = existing?.previous;
    if (existing) {
      if (existing.shopperId === input.shopperId) outcome = 'already';
      else {
        outcome = 'relinked';
        previous = [{ shopperId: existing.shopperId, linkedAt: existing.linkedAt, until: now }, ...(existing.previous ?? [])].slice(0, 10);
      }
    }

    const link: VisitorLink = {
      visitorId: input.visitorId, shopperId: input.shopperId,
      linkedAt: outcome === 'already' ? existing!.linkedAt : now,
      assurance: input.assurance, source: input.source,
      ...(previous && previous.length ? { previous } : {}),
    };

    const shopper: ShopperRecord = (await this.shopper(input.shopperId)) ?? {
      shopperId: input.shopperId, createdAt: now, salted: input.salted, visitors: [],
    };
    if (!shopper.visitors.some((v) => v.visitorId === input.visitorId)) {
      shopper.visitors.push({ visitorId: input.visitorId, linkedAt: now, assurance: input.assurance, source: input.source });
      shopper.visitors = shopper.visitors.slice(-50);
    }

    if (outcome !== 'already') await this.kv.put(this.vkey(input.visitorId), JSON.stringify(link), { expirationTtl: LINK_TTL_S });
    await this.kv.put(this.skey(input.shopperId), JSON.stringify(shopper), { expirationTtl: LINK_TTL_S });
    return { link, shopper, outcome };
  }

  /** Make sure a shopper record exists, for a person seen first through an import. */
  async ensureShopper(shopperId: string, salted: boolean, now = Date.now()): Promise<ShopperRecord> {
    const existing = await this.shopper(shopperId);
    if (existing) return existing;
    const created: ShopperRecord = { shopperId, createdAt: now, salted, visitors: [] };
    await this.kv.put(this.skey(shopperId), JSON.stringify(created), { expirationTtl: LINK_TTL_S });
    return created;
  }

  /**
   * CW28. Forget a person: every browser's link and the person's record. Returns
   * the visitor ids that were linked, so the caller can erase each browser's
   * profile and ledger rows too. Idempotent; a second call finds nothing.
   */
  async erase(shopperId: string): Promise<{ visitors: string[]; sessions: string[] }> {
    const rec = await this.shopper(shopperId);
    const visitors = rec ? rec.visitors.map((v) => v.visitorId) : [];
    const sessions: string[] = [];
    for (const v of visitors) {
      const link = await this.visitorLink(v);
      if (link?.ownSessionId) sessions.push(link.ownSessionId);
      await this.kv.delete(this.vkey(v));
    }
    await this.kv.delete(this.skey(shopperId));
    return { visitors, sessions };
  }

  /** CW28. Forget one browser's link only, when it was never anyone's or the person is being kept. */
  async eraseVisitor(visitorId: string): Promise<{ ownSessionId: string | null }> {
    const link = await this.visitorLink(visitorId);
    await this.kv.delete(this.vkey(visitorId));
    return { ownSessionId: link?.ownSessionId ?? null };
  }

  /** CW28. Remember where the browser's own record lives, once the link has forwarded it. */
  async noteOwnSession(visitorId: string, sessionId: string): Promise<void> {
    const link = await this.visitorLink(visitorId);
    if (!link || link.ownSessionId === sessionId) return;
    await this.kv.put(this.vkey(visitorId), JSON.stringify({ ...link, ownSessionId: sessionId }), { expirationTtl: LINK_TTL_S });
  }

  async noteHistory(shopperId: string, rows: number, latestAt: number, salted: boolean, now = Date.now()): Promise<void> {
    const rec = await this.ensureShopper(shopperId, salted, now);
    const prev = rec.history;
    rec.history = {
      rows: (prev?.rows ?? 0) + rows,
      latestAt: Math.max(prev?.latestAt ?? 0, latestAt),
      appliedAt: now,
    };
    await this.kv.put(this.skey(shopperId), JSON.stringify(rec), { expirationTtl: LINK_TTL_S });
  }
}

// src/ledger/erasure.ts
// Doc 22 §15, CW28: erasure across the ledger. The ledger is append-only and
// its R2 partition is the warehouse's export, so "delete this visitor's rows"
// is two things with one list between them.
//
// A TOMBSTONE per visitor, written the moment erasure is requested, that every
// reader honours at once: the day report, the point lookup, the replay and the
// export listing all drop a row whose visitor is tombstoned and whose time is
// at or before the erasure. And a scheduled REWRITE that walks the tenant's
// partition newest day first over the retention window, removes those rows
// from the batch objects, deletes an object that empties, and retires the
// tombstone with its counts and no visitor id. A run is capped, resumes where
// it stopped, and is idempotent: a day done twice removes nothing the second
// time. Aggregates are untouched, because counts are not personal data.
//
// The rows a visitor produces AFTER the erasure are new evidence, kept: an
// erasure is a point in time, not a ban. The retention window is the ledger's
// own (the bucket's lifecycle rule must match it) and is the number Tapestry's
// privacy team agrees; the default is the design's 90 days.

import type { Env } from '@/types/env';

export interface Tombstone {
  tenant: string;
  visitor_id: string;
  /** When erasure was requested. Rows at or before it are hidden, then removed. */
  erased_at: number;
  actor: string;
  /** The oldest day (UTC, YYYY-MM-DD) the rewrite has already cleaned for this visitor; absent before the first pass. */
  done_through?: string;
  rows_removed: number;
  objects_rewritten: number;
  objects_deleted: number;
}

/** What remains after the rewrite: the audit of an erasure, with the visitor id replaced by a hash. */
export interface RetiredTombstone {
  tenant: string;
  visitor_hash: string;
  erased_at: number;
  rewritten_at: number;
  window_days: number;
  rows_removed: number;
  objects_rewritten: number;
  objects_deleted: number;
}

export interface R2Erasable {
  put(key: string, body: string, opts?: unknown): Promise<unknown>;
  get(key: string): Promise<{ text(): Promise<string> } | null>;
  delete(key: string): Promise<unknown>;
  list(opts: { prefix: string; cursor?: string; limit?: number }): Promise<{ objects: Array<{ key: string }>; truncated: boolean; cursor?: string }>;
}
export type R2Readable = Pick<R2Erasable, 'get' | 'list'>;

export const DEFAULT_RETENTION_DAYS = 90;
const DAY = 86_400_000;

export const pendingPrefix = (tenant: string) => `erasures/${tenant}/pending/`;
export const retiredPrefix = (tenant: string) => `erasures/${tenant}/retired/`;
export const tombstoneKey = (tenant: string, visitorId: string) => `${pendingPrefix(tenant)}${encodeURIComponent(visitorId)}.json`;

export const dayOf = (ms: number): string => new Date(ms).toISOString().slice(0, 10);
const msOfDay = (day: string): number => Date.UTC(+day.slice(0, 4), +day.slice(5, 7) - 1, +day.slice(8, 10));
const prevDay = (day: string): string => dayOf(msOfDay(day) - DAY);

/** FNV-1a over the id, with its length: enough to tell audit rows apart, and no way back to the id. */
export function visitorHash(id: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < id.length; i++) { h ^= id.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return `${h.toString(16).padStart(8, '0')}-${id.length}`;
}

/** The retention window in days: `LEDGER_RETENTION_DAYS`, or the design's default. */
export function retentionDays(env: Pick<Env, 'LEDGER_RETENTION_DAYS'>): number {
  const n = Number(env.LEDGER_RETENTION_DAYS);
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_RETENTION_DAYS;
}

export async function listKeys(r2: R2Readable, prefix: string): Promise<string[]> {
  const out: string[] = [];
  let cursor: string | undefined;
  do {
    const page = await r2.list({ prefix, cursor, limit: 1000 });
    for (const o of page.objects) out.push(o.key);
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return out.sort();
}

/** Every pending tombstone for the tenant, by visitor id. */
export async function loadTombstones(r2: R2Readable, tenant: string): Promise<Map<string, Tombstone>> {
  const out = new Map<string, Tombstone>();
  for (const key of await listKeys(r2, pendingPrefix(tenant))) {
    const obj = await r2.get(key);
    if (!obj) continue;
    try {
      const t = JSON.parse(await obj.text()) as Tombstone;
      if (t && typeof t.visitor_id === 'string' && typeof t.erased_at === 'number') out.set(t.visitor_id, t);
    } catch { /* an unreadable tombstone hides nothing; the rewrite reports it */ }
  }
  return out;
}

/** Is this row hidden: its visitor is tombstoned and it happened at or before the erasure. */
export function hidden(tombs: ReadonlyMap<string, Pick<Tombstone, 'erased_at'>>, rec: { visitor_id: string; ts: number }): boolean {
  const t = tombs.get(rec.visitor_id);
  return t !== undefined && rec.ts <= t.erased_at;
}

export function withoutErased<T extends { visitor_id: string; ts: number }>(records: readonly T[], tombs: ReadonlyMap<string, Pick<Tombstone, 'erased_at'>>): T[] {
  return tombs.size ? records.filter((r) => !hidden(tombs, r)) : [...records];
}

/** Write (or refresh) the visitor's tombstone. Refreshing restarts the rewrite window; the counts so far are kept. */
export async function writeTombstone(r2: R2Erasable, tenant: string, visitorId: string, actor: string, now = Date.now()): Promise<{ key: string; tombstone: Tombstone }> {
  const key = tombstoneKey(tenant, visitorId);
  let prior: Tombstone | null = null;
  try { const obj = await r2.get(key); prior = obj ? (JSON.parse(await obj.text()) as Tombstone) : null; } catch { prior = null; }
  const tombstone: Tombstone = {
    tenant, visitor_id: visitorId, erased_at: Math.max(now, prior?.erased_at ?? 0), actor,
    rows_removed: prior?.rows_removed ?? 0, objects_rewritten: prior?.objects_rewritten ?? 0, objects_deleted: prior?.objects_deleted ?? 0,
  };
  await r2.put(key, JSON.stringify(tombstone), { httpMetadata: { contentType: 'application/json' } });
  return { key, tombstone };
}

export interface RewriteResult {
  tenant: string;
  /** Pending tombstones at the start of the run. */
  tombstones: number;
  /** The days this run cleaned, newest first. */
  days: string[];
  objects_opened: number;
  objects_rewritten: number;
  objects_deleted: number;
  rows_removed: number;
  /** Tombstones whose window is complete: retired to the audit prefix with a hash, no visitor id. */
  retired: number;
  /** Tombstones still pending after the run. */
  remaining: number;
  /** The run stopped at its object cap with days left; the next run continues. */
  more: boolean;
}

/**
 * The scheduled rewrite. For every pending tombstone the days to clean are the
 * erasure day back through the retention window; a day is cleaned only once it
 * is over (the queue has drained it), newest first, contiguously, so
 * `done_through` is always the oldest day cleaned and a resumed run continues
 * from the day after it. All tombstones share one pass over a day.
 */
export async function rewriteErasures(r2: R2Erasable, tenant: string, opts: { now?: number; retentionDays?: number; maxObjects?: number } = {}): Promise<RewriteResult> {
  const now = opts.now ?? Date.now();
  const window = opts.retentionDays ?? DEFAULT_RETENTION_DAYS;
  const cap = opts.maxObjects ?? 5000;
  const today = dayOf(now);
  const tombs = await loadTombstones(r2, tenant);
  const result: RewriteResult = { tenant, tombstones: tombs.size, days: [], objects_opened: 0, objects_rewritten: 0, objects_deleted: 0, rows_removed: 0, retired: 0, remaining: tombs.size, more: false };
  if (!tombs.size) return result;

  const floorOf = (t: Tombstone) => dayOf(t.erased_at - window * DAY);
  const nextOf = (t: Tombstone) => (t.done_through ? prevDay(t.done_through) : dayOf(t.erased_at));
  /** The days a tombstone still needs, newest first; none if its window is done or its next day is not over yet. */
  const daysFor = (t: Tombstone): string[] => {
    const out: string[] = [];
    for (let d = nextOf(t); d >= floorOf(t) && d < today; d = prevDay(d)) out.push(d);
    return out;
  };
  const wanted = new Map<string, Tombstone[]>();
  for (const t of tombs.values()) for (const d of daysFor(t)) (wanted.get(d) ?? wanted.set(d, []).get(d)!).push(t);
  const days = [...wanted.keys()].sort().reverse();
  const touched = new Set<Tombstone>();

  for (const day of days) {
    if (result.objects_opened >= cap) { result.more = true; break; }
    const targets = wanted.get(day)!;
    const eraseAt = new Map(targets.map((t) => [t.visitor_id, t.erased_at] as const));
    for (const key of await listKeys(r2, `${tenant}/${day}/`)) {
      result.objects_opened++;
      const obj = await r2.get(key);
      if (!obj) continue;
      const kept: string[] = [];
      const removedBy = new Map<string, number>();
      for (const line of (await obj.text()).split('\n')) {
        if (!line) continue;
        let rec: { visitor_id?: unknown; ts?: unknown } | null = null;
        try { rec = JSON.parse(line) as { visitor_id?: unknown; ts?: unknown }; } catch { kept.push(line); continue; }
        const at = typeof rec?.visitor_id === 'string' ? eraseAt.get(rec.visitor_id) : undefined;
        if (at !== undefined && typeof rec?.ts === 'number' && rec.ts <= at) { removedBy.set(rec.visitor_id as string, (removedBy.get(rec.visitor_id as string) ?? 0) + 1); continue; }
        kept.push(line);
      }
      if (!removedBy.size) continue;
      const emptied = kept.length === 0;
      if (emptied) { await r2.delete(key); result.objects_deleted++; } else { await r2.put(key, kept.join('\n') + '\n'); result.objects_rewritten++; }
      for (const [visitor, n] of removedBy) {
        const t = tombs.get(visitor)!;
        t.rows_removed += n; result.rows_removed += n;
        if (emptied) t.objects_deleted++; else t.objects_rewritten++;
      }
    }
    for (const t of targets) { t.done_through = day; touched.add(t); }
    result.days.push(day);
  }

  for (const t of touched) {
    const key = tombstoneKey(tenant, t.visitor_id);
    if (t.done_through && t.done_through <= floorOf(t)) {
      const retired: RetiredTombstone = {
        tenant, visitor_hash: visitorHash(t.visitor_id), erased_at: t.erased_at, rewritten_at: now, window_days: window,
        rows_removed: t.rows_removed, objects_rewritten: t.objects_rewritten, objects_deleted: t.objects_deleted,
      };
      await r2.put(`${retiredPrefix(tenant)}${t.erased_at.toString(36)}-${retired.visitor_hash}.json`, JSON.stringify(retired), { httpMetadata: { contentType: 'application/json' } });
      await r2.delete(key);
      result.retired++; result.remaining--;
    } else {
      await r2.put(key, JSON.stringify(t), { httpMetadata: { contentType: 'application/json' } });
    }
  }
  return result;
}

/**
 * The ledger half of an erasure, in one call for the identity route to make:
 * the tombstone, so every reader hides the rows now and the rewrite removes
 * them; and the visitor's own ring of served decisions, emptied. The profile
 * and the long index live in the shopper's object, which the identity route
 * erases itself.
 */
export async function eraseVisitorLedger(env: Pick<Env, 'STORAGE' | 'DECISION_RING'>, tenant: string, visitorId: string, actor: string, now = Date.now()): Promise<{ ok: true; tombstone: { key: string; erased_at: number }; ring: 'reset' | 'unbound' | 'failed' }> {
  const { key, tombstone } = await writeTombstone(env.STORAGE as unknown as R2Erasable, tenant, visitorId, actor, now);
  let ring: 'reset' | 'unbound' | 'failed' = 'unbound';
  const ns = env.DECISION_RING;
  if (ns) {
    try {
      const res = await ns.get(ns.idFromName(`${tenant}:${visitorId}`)).fetch('https://learn/reset', { method: 'POST' });
      ring = res.ok ? 'reset' : 'failed';
    } catch { ring = 'failed'; }
  }
  return { ok: true, tombstone: { key, erased_at: tombstone.erased_at }, ring };
}

// src/routes/identity.ts
// ---------------------------------------------------------------------------
// CW25 — identity stitching (scope appendix §1.12, ledger 20 row 2).
//
//   POST /v1/:tenant/identity/link      the site says who this browser is
//   POST /v1/:tenant/identity/detach    this browser stops being anyone (logout)
//   POST /v1/:tenant/identity/resolve   account id → shopper id, for the warehouse
//   GET  /v1/:tenant/identity/visitor/:visitorId   which person, if any
//   GET  /v1/:tenant/identity/shopper/:shopperId   which browsers, and the history applied
//   POST /v1/:tenant/identity/events    historical rows, JSON or CSV
//   POST /v1/:tenant/identity/erase     the right to be forgotten: links, profiles, ledger rows
//
// Mounted under /v1, so the site-key gate (CW10) covers everything here. The
// link and detach are the SDK's calls. Linking always also requires a backend
// signed assertion; missing verification configuration refuses it. The rest is the
// data team's and wants the operator token, like the ledger routes.
// ---------------------------------------------------------------------------

import { Hono } from 'hono';
import { z } from 'zod';
import type { Env } from '@/types/env';
import type { TenantVariables } from '@/tenancy/tenant';
import { jwt } from '@/middleware/auth';
import { SessionManager } from '@/services/SessionManager';
import { verifyAssertion } from '@/identity/assertion';
import { linkVisitor, validVisitorId } from '@/identity/link';
import { IdentityStore } from '@/identity/store';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';
import { applyHistory, historyRowSchema, parseHistoryCsv, MAX_ROWS } from '@/identity/history';
import { eraseSubject } from '@/identity/erase';
import type { AuthContext } from '@/middleware/auth';
import { requireShopper, shopperPrincipal, capabilityToken, verifySessionCapability, issueSessionCapability, assertSessionTarget, SessionAccessError } from '@/identity/sessionCapability';
import { anonymousWithConsent, establishRefusal, ownedConsent } from '@/identity/consentContinuity';
import { consentFromCookies, intersectConsent, refusalHints } from '@/content/consent';
import { tenantForRequest } from '@/tenancy/middleware';

export const identityRoutes = new Hono<{ Bindings: Env; Variables: TenantVariables }>();

const TENANT = /^[a-z0-9][a-z0-9_-]{0,63}$/i;

const linkSchema = z.object({
  visitorId: z.string().trim().min(1).max(200),
  accountId: z.string().trim().min(1).max(200),
  source: z.enum(['login', 'signup', 'checkout', 'import', 'other']).default('login'),
  exp: z.number().int().optional(),
  assertion: z.string().min(1).max(200).optional(),
});

function tenantOf(c: { req: { param(name: string): string | undefined } }): string | null {
  const t = (c.req.param('tenant') ?? '').trim();
  return TENANT.test(t) ? t : null;
}

/**
 * The link. Returns the id the client carries from now on. On the session host
 * the response also sets the session cookie to the person's session, so every
 * tab on this device lands there on its next request without any forwarding.
 */
identityRoutes.post('/:tenant/identity/session', async (c) => {
  const tenant = tenantOf(c);
  if (!tenant || tenant !== (c.get('tenant') ?? tenantForRequest(c.env, c.req.raw))) throw new SessionAccessError();
  let body: { consent?: unknown } = {};
  try { const text = await c.req.text(); if (text) body = JSON.parse(text); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const hints = intersectConsent(consentFromCookies(c.req.header('Cookie')), refusalHints(body?.consent));
  const token = capabilityToken(c.req.raw);
  let session;
  if (token === null) session = await anonymousWithConsent(c.env, tenant, hints);
  else {
    const principal = await verifySessionCapability(c.env, token, tenant);
    const consent = intersectConsent(await ownedConsent(c.env, principal, token), hints);
    session = { ...principal, capability: token, consent: await establishRefusal(c.env, principal, token, consent) };
  }
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, session });
});

identityRoutes.post('/:tenant/identity/link', requireShopper(), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: unknown;
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const parsed = linkSchema.safeParse(body);
  if (!parsed.success) return c.json({ ok: false, error: parsed.error.issues[0]?.message ?? 'invalid body' }, 400);
  const { visitorId, accountId, source, exp, assertion } = parsed.data;
  const principal = shopperPrincipal(c.req.raw);
  assertSessionTarget(principal, visitorId);

  if (!validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  if (isShopperId(visitorId)) {
    // A browser already carrying a person's id is signed in as that person.
    // Linking it to another account would fold one person into another.
    return c.json({ ok: false, error: 'this browser already carries a shopper id; detach first' }, 409);
  }

  const verdict = await verifyAssertion(c.env, tenant, { visitorId, accountId, exp, assertion });
  if (!verdict.ok) return c.json({ ok: false, error: verdict.reason }, 401);

  const result = await linkVisitor(c.env, tenant, { visitorId, accountId, source, assurance: verdict.assurance, principal, capability: capabilityToken(c.req.raw)!, cookieHeader: c.req.header('Cookie') });
  if (!result.sessionId) throw new SessionAccessError();
  const session = { ...await issueSessionCapability(c.env, { tenant, subject: result.shopperId, sessionId: result.sessionId, kind: 'recognized' }), consent: result.consent };
  for (const h of result.cookieHeaders) c.header('Set-Cookie', h, { append: true });
  c.header('Cache-Control', 'no-store');
  return c.json({
    ok: true,
    tenant,
    shopperId: result.shopperId,
    visitorId: result.visitorId,
    outcome: result.outcome,
    assurance: result.assurance,
    salted: isSalted(c.env),
    audiences: result.audiences,
    changes: { entered: result.changes.entered, exited: result.changes.exited },
    // What the client does next, spelled out so no SDK has to guess.
    carry: result.shopperId,
    session,
  });
});

/**
 * Detach keeps the person's profile, transfers only refusal to fresh anonymous
 * authority, and clears private mirrors without expiring the refusal cookies.
 */
identityRoutes.post('/:tenant/identity/detach', requireShopper(), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const sm = new SessionManager(c.env, { tenant });
  const consent = await ownedConsent(c.env, shopperPrincipal(c.req.raw), capabilityToken(c.req.raw)!, c.req.header('Cookie'));
  const session = await anonymousWithConsent(c.env, tenant, consent);
  for (const h of sm.clearCookieHeaders()) c.header('Set-Cookie', h, { append: true });
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, tenant, detached: true, session });
});

/** The warehouse's join key for an account, without the warehouse holding the salt. */
identityRoutes.post('/:tenant/identity/resolve', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: { accountIds?: unknown } = {};
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const ids = Array.isArray(body.accountIds) ? body.accountIds.filter((x): x is string => typeof x === 'string' && x.trim() !== '').slice(0, 1000) : [];
  if (ids.length === 0) return c.json({ ok: false, error: 'accountIds: string[] required' }, 400);
  const resolved: Record<string, string> = {};
  for (const id of ids) resolved[id] = await shopperIdFor(c.env, tenant, id);
  return c.json({ ok: true, tenant, salted: isSalted(c.env), resolved });
});

identityRoutes.get('/:tenant/identity/visitor/:visitorId', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const visitorId = (c.req.param('visitorId') ?? '').trim();
  if (!validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  const store = new IdentityStore(c.env.SESSIONS as never, tenant);
  const link = await store.visitorLink(visitorId);
  return c.json({ ok: true, tenant, visitorId, shopperId: isShopperId(visitorId) ? visitorId : (link?.shopperId ?? null), link });
});

identityRoutes.get('/:tenant/identity/shopper/:shopperId', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const shopperId = (c.req.param('shopperId') ?? '').trim();
  if (!isShopperId(shopperId)) return c.json({ ok: false, error: 'not a shopper id' }, 400);
  const store = new IdentityStore(c.env.SESSIONS as never, tenant);
  const rec = await store.shopper(shopperId);
  if (!rec) return c.json({ ok: false, error: 'unknown shopper' }, 404);
  return c.json({ ok: true, tenant, shopper: rec });
});

/**
 * Historical rows. `application/json` with `{ rows: [...] }`, or `text/csv`
 * with a header row. Each row is validated; a bad row fails the request, a row
 * that names nobody or carries no registry attribute is skipped and reported.
 */
identityRoutes.post('/:tenant/identity/events', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const ct = (c.req.header('Content-Type') ?? '').toLowerCase();
  let raw: unknown[];
  if (ct.includes('text/csv')) {
    raw = parseHistoryCsv(await c.req.text());
  } else {
    let body: { rows?: unknown } = {};
    try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
    raw = Array.isArray(body.rows) ? body.rows : [];
  }
  if (raw.length === 0) return c.json({ ok: false, error: 'no rows' }, 400);
  if (raw.length > MAX_ROWS) return c.json({ ok: false, error: `at most ${MAX_ROWS} rows per request` }, 413);
  const parsed = z.array(historyRowSchema).safeParse(raw);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    return c.json({ ok: false, error: `row ${String(issue?.path[0] ?? '?')}: ${issue?.message ?? 'invalid'}` }, 400);
  }
  const report = await applyHistory(c.env, tenant, parsed.data);
  return c.json({ ok: true, tenant, ...report });
});

/**
 * CW28. Forget a person, or an unlinked browser: the link table, every
 * profile, and the ledger rows (tombstoned at once, rewritten nightly by the
 * ledger's job). Operator token. The receipt lists what was erased and what
 * this cannot reach.
 */
identityRoutes.post('/:tenant/identity/erase', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: { visitorId?: unknown; shopperId?: unknown } = {};
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const visitorId = typeof body.visitorId === 'string' ? body.visitorId.trim() : '';
  const shopperId = typeof body.shopperId === 'string' ? body.shopperId.trim() : '';
  if (!visitorId && !shopperId) return c.json({ ok: false, error: 'visitorId or shopperId required' }, 400);
  if (visitorId && !validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  if (shopperId && !isShopperId(shopperId)) return c.json({ ok: false, error: 'shopperId is not a shopper id' }, 400);
  const actor = (c as unknown as { get: (k: 'auth') => AuthContext | undefined }).get('auth')?.user?.sub ?? 'operator';
  const receipt = await eraseSubject(c.env, tenant, { ...(visitorId ? { visitorId } : {}), ...(shopperId ? { shopperId } : {}) }, actor);
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, ...receipt });
});

// src/routes/identity.test.ts
//
// CW25 through the wire, on the session host: a phone and a laptop browse as
// strangers, both sign in to the same account, and the person is the sum. Then
// the rules around the edges: the assertion, the shopper-id refusal, the shared
// computer, detach, history in both formats, and who may ask what.

import { describe, it, expect, beforeEach, vi } from 'vitest';
import * as jose from 'jose';
import type { Env } from '@/types/env';
import { identityRoutes } from '@/routes/identity';
import { SessionManager } from '@/services/SessionManager';
import { DEFAULT_REFLEX_CONFIG, apply, audienceKey, emptyState, snapshot, type ReflexState } from '@/reflex/core';
import { signAssertion } from '@/identity/assertion';
import { shopperIdFor } from '@/identity/shopperId';
import { createCore } from '@/sdk/core';
import { createIdentity } from '@/sdk/identify';
import { memoryHost } from '@/sdk/memoryHost';
import { issueSessionCapability, SHOPPER_HEADER } from '@/identity/sessionCapability';

class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string }) { const p = o?.prefix ?? ''; return { keys: [...this.store.keys()].filter((k) => k.startsWith(p)).map((name) => ({ name })) }; }
}

const cfg = DEFAULT_REFLEX_CONFIG;
const TABBY = audienceKey('line', 'Tabby');

/** Enough of R2 for the ledger's tombstones: put, get, delete, list by prefix. */
class FakeR2 {
  store = new Map<string, string>();
  async put(key: string, body: string) { this.store.set(key, body); }
  async get(key: string) { const v = this.store.get(key); return v === undefined ? null : { text: async () => v }; }
  async delete(key: string) { this.store.delete(key); }
  async list(o: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(o.prefix)).map((key) => ({ key })), truncated: false }; }
}

const mkEnv = (over: Record<string, unknown> = {}): Env => ({
  CACHE: new FakeKV(), SESSIONS: new FakeKV(), STORAGE: new FakeR2(), ENVIRONMENT: 'test', CONNECTOR_MODE: 'mock',
  JWT_SECRET: 'w0202-synthetic-route-signing-material', JWT_ISSUER: 'i', JWT_AUDIENCE: 'a', IDENTITY_SECRETS: 'coach:s3cret', ...over,
} as unknown as Env);
const token = () => new jose.SignJWT({ sub: 'ops' }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt().setIssuer('i').setAudience('a').setExpirationTime('5m').sign(new TextEncoder().encode('w0202-synthetic-route-signing-material'));

const browse = (values: string[], at: number): ReflexState => {
  let s = emptyState(cfg);
  values.forEach((v, i) => { s = apply(s, { action: 'product_view', touches: [{ dim: 'line', value: v }] }, at + i * 1000, cfg).state; });
  return s;
};

let env: Env;
let auth: Record<string, string>;
let ownedIds = new Map<string, string>();

async function seedDevice(visitorId: string, sessionId: string, values: string[]) {
  ownedIds.set(visitorId, sessionId);
  const sm = new SessionManager(env);
  // Built a few seconds ago, not at T0: the route merges at Date.now(), and a vector from 2023 is dust by now.
  await sm.createOrUpdateSession(sessionId, visitorId, { reflex: browse(values, Date.now() - 5_000), attributes: { product_views: values.length } });
}

async function call(path: string, init: RequestInit & { json?: unknown } = {}) {
  const headers: Record<string, string> = { ...(init.headers as Record<string, string> ?? {}) };
  let body = init.body;
  if (init.json !== undefined) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(init.json); }
  const res = await identityRoutes.request(path, { ...init, headers, body }, env);
  return { status: res.status, body: (await res.json()) as Record<string, any>, headers: res.headers };
}

async function ownedCall(path: string, init: RequestInit & { json?: unknown }) {
  const visitorId = (init.json as { visitorId?: string })?.visitorId ?? 'vis-00000000-0000-4000-8000-000000000099';
  const subject = /^[A-Za-z0-9_.-]+$/.test(visitorId) ? visitorId : 'vis-00000000-0000-4000-8000-000000000099';
  const session = await issueSessionCapability(env, { tenant: 'coach', subject, sessionId: ownedIds.get(subject) ?? 's-owned-fresh', kind: subject.startsWith('sh_') ? 'recognized' : 'anonymous' });
  return call(path, { ...init, headers: { ...init.headers, [SHOPPER_HEADER]: session.capability } });
}

// Explicit positive-fixture signing only. The SDK transport below never uses this helper.
async function signedCall(path: string, init: RequestInit & { json?: unknown }) {
  const body = init.json as { visitorId: string; accountId: string };
  const exp = Math.floor(Date.now() / 1000) + 120;
  const assertion = await signAssertion('s3cret', 'coach', body.visitorId, body.accountId, exp);
  return ownedCall(path, { ...init, json: { ...body, exp, assertion } });
}

beforeEach(async () => {
  env = mkEnv();
  ownedIds = new Map();
  auth = { Authorization: `Bearer ${await token()}` };
});

describe('the link, on the session host', () => {
  it('a phone signs in: the response names the person, sets the cookie, and the old cookie reads the person', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby', 'Tabby']);
    const r = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.outcome).toBe('linked');
    expect(r.body.assurance).toBe('signed');
    expect(r.body.shopperId).toBe(await shopperIdFor(env, 'coach', 'acct-1001'));
    expect(r.body.carry).toBe(r.body.shopperId);
    expect(r.body.audiences).toContain(TABBY);
    const cookies = r.headers.get('set-cookie') ?? '';
    expect(cookies).toContain('opt_session_id=');
    expect(cookies).toContain(`opt_user_id=${r.body.shopperId}`);
    expect(cookies).not.toContain('opt_session_id=s-phone');

    const sm = new SessionManager(env);
    expect((await sm.getSession('s-phone'))?.userId).toBe(r.body.shopperId);
  });

  it('a laptop signs in to the same account: cross-device, the person is the sum', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby']);
    await seedDevice('vis-00000000-0000-4000-8000-000000000002', 's-laptop', ['Rogue', 'Rogue', 'Tabby']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const b = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000002', accountId: 'acct-1001', source: 'checkout' } });
    expect(b.body.shopperId).toBe(a.body.shopperId);
    expect(b.body.outcome).toBe('linked');

    const sm = new SessionManager(env);
    const person = await sm.getSessionByUserId(b.body.shopperId);
    const snap = snapshot(person!.reflex!, Date.now(), cfg);
    expect(Object.keys(snap.dims.line).sort()).toEqual(['Rogue', 'Tabby']);
    expect(person!.attributes.product_views).toBe(5);
    expect(person!.metadata.visitCount).toBe(2);
    // Either browser resolves to the person.
    expect((await sm.getSession('s-phone'))?.userId).toBe(b.body.shopperId);
    expect((await sm.getSession('s-laptop'))?.userId).toBe(b.body.shopperId);
  });

  it('the old anonymous grant cannot follow the linked browser into the person', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const b = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    expect(b.status).toBe(401);
    expect((await new SessionManager(env).getSessionByUserId(a.body.shopperId))!.attributes.product_views).toBe(1);
  });

  it('a shared computer requires detach and a newly owned browser before linking another account', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby', 'Tabby']);
    const first = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const refused = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-2002' } });
    expect(refused.status).toBe(401);
    const detached = await call('/coach/identity/detach', { method: 'POST', headers: { [SHOPPER_HEADER]: first.body.session.capability } });
    const fresh = detached.body.session;
    const exp = Math.floor(Date.now() / 1000) + 120;
    const assertion = await signAssertion('s3cret', 'coach', fresh.subject, 'acct-2002', exp);
    const second = await call('/coach/identity/link', { method: 'POST', headers: { [SHOPPER_HEADER]: fresh.capability }, json: { visitorId: fresh.subject, accountId: 'acct-2002', exp, assertion } });
    expect(second.status).toBe(200); expect(second.body.shopperId).not.toBe(first.body.shopperId); expect(second.body.audiences).toEqual([]);
    expect((await new SessionManager(env).getSessionByUserId(first.body.shopperId))?.reflex?.audiences).toContain(TABBY);
  });

  it('refuses to link a browser that already carries a shopper id', async () => {
    const sh = await shopperIdFor(env, 'coach', 'acct-1001');
    const r = await ownedCall('/coach/identity/link', { method: 'POST', json: { visitorId: sh, accountId: 'acct-2002' } });
    expect(r.status).toBe(409);
  });

  it('a browser with no session yet links fine: the person starts empty', async () => {
    const r = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000004', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.audiences).toEqual([]);
    const sm = new SessionManager(env);
    expect(await sm.resolveSessionIdByUserId('vis-00000000-0000-4000-8000-000000000004')).toBe(await sm.resolveSessionIdByUserId(r.body.shopperId));
  });

  it('validates the body and the tenant', async () => {
